changeSet.sql:
CREATE TABLE owned_plots ( id uuid NOT NULL PRIMARY KEY, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
buyer_user_id uuid NOT NULL REFERENCES users (id), transaction_id uuid REFERENCES transactions (id), plot_id uuid NOT NULL REFERENCES plots (id), estate_id uuid NOT NULL REFERENCES estates (id), seller_tenant_id uuid NOT NULL REFERENCES organizations (id), status varchar(24) NOT NULL, plan varchar(16) NOT NULL, intent varchar(16) NOT NULL, base_price numeric(19, 4) NOT NULL, corner_premium_pct numeric(5, 2), total_price numeric(19, 4) NOT NULL, currency varchar(3) NOT NULL, acquired_at timestamp(6) with time zone NOT NULL, supersedes uuid REFERENCES owned_plots (id),
CONSTRAINT chk_owned_plots_status CHECK (status IN ( 'RESERVED', 'PENDING_VERIFICATION', 'ALLOCATED', 'INSTALLMENT_ACTIVE', 'COMPLETED', 'IN_ARREARS', 'UPGRADE_PENDING', 'TRANSFERRED', 'SUPERSEDED')), CONSTRAINT chk_owned_plots_prices CHECK (base_price > 0 AND total_price >= base_price) ); -- One sale, one owned record. CREATE UNIQUE INDEX uq_owned_plots_transaction ON owned_plots (transaction_id) WHERE transaction_id IS NOT NULL; -- Never two owners of one plot at once: only a retired record may share it. CREATE UNIQUE INDEX uq_owned_plots_one_owner ON owned_plots (plot_id) WHERE deleted = false AND status NOT IN ('TRANSFERRED', 'SUPERSEDED'); CREATE INDEX idx_owned_plots_buyer ON owned_plots (buyer_user_id, acquired_at DESC); REVOKE DELETE, TRUNCATE ON owned_plots FROM ${appDbUsername};
COMMENT ON TABLE owned_plots IS 'What a buyer owns, created when finance verifies the sale (same transaction as the plot becoming SOLD). Buyer-owned: tenant_id null, the seller is seller_tenant_id; not RLS-policied, reached by buyer_user_id only. Never deleted. See AGENTS.md, "Portfolio".'; COMMENT ON COLUMN owned_plots.status IS 'All nine of the frontend''s account statuses are legal; only COMPLETED is written today (an outright sale, verified). RESERVED and PENDING_VERIFICATION are shown from the checkout, never stored here; ALLOCATED needs issued documents; the installment, upgrade and resale statuses need flows that do not exist. TRANSFERRED (to another buyer, by resale) and SUPERSEDED (the same buyer''s equity moved to another plot, by upgrade) are different facts and must never be merged.'; COMMENT ON COLUMN owned_plots.base_price IS 'Copied from the sale, never recomputed: what was agreed. corner_premium_pct is null for a plot sold without one.';
